@Test
public void testLazyMapFactory_4_oe() {
    final Factory<Integer> factory = FactoryUtils.constantFactory(Integer.valueOf(5));
    Map<Object, Object> map = MapUtils.lazyMap(new HashMap<>(), factory);
    try {
        map = MapUtils.lazyMap(new HashMap<>(), (Factory<Object>) null);
    } catch (final NullPointerException e) {
    }
    try {
        map = MapUtils.lazyMap((Map<Object, Object>) null, factory);
    } catch (final NullPointerException e) {
    }
    final Transformer<Object, Integer> transformer = TransformerUtils.asTransformer(factory);
    map = MapUtils.lazyMap(new HashMap<>(), transformer);
    assertTrue(map instanceof LazyMap);
}

mut_docstring:
/**
     * Returns a "lazy" map whose values will be created on demand.
     * <p>
     * When the key passed to the returned map's {@link Map#get(Object)}
     * method is not present in the map, then the factory will be used
     * to create a new object and that object will become the value
     * associated with that key.
     * <p>
     * For instance:
     * <pre>
     * Factory factory = new Factory() {
     *     public Object create() {
     *         return new Date();
     *     }
     * }
     * Map lazyMap = MapUtils.lazyMap(new HashMap(), factory);
     * Object obj = lazyMap.get("test");
     * </pre>
     *
     * After the above code is executed, <code>obj</code> will contain
     * a new <code>Date</code> instance.  Furthermore, that <code>Date</code>
     * instance is the value for the <code>"test"</code> key in the map.
     *
     * @param <K>  the key type
     * @param <V>  the value type
     * @param map  the map to make lazy, must not be null
     * @param factory  the factory for creating new objects, must not be null
     * @return a lazy map backed by the given map
     * @throws NullPointerException  if the Map or Factory is null
     */

mut_method_definition:
public static <K, V> IterableMap<K, V> lazyMap(final Map<K, V> map, final Factory<? extends V> factory) {
        return LazyMap.lazyMap(map, factory);
    }

