public void testGetValueByIndex_1_oe() {
    resetEmpty();
    ListOrderedMap<K, V> lom = getMap();
    try {
        lom.getValue(0);
    } catch (final IndexOutOfBoundsException ex) {}
    try {
        lom.getValue(-1);
    } catch (final IndexOutOfBoundsException ex) {}

    resetFull();
    lom = getMap();
    try {
        lom.getValue(-1);
    } catch (final IndexOutOfBoundsException ex) {}
    try {
        lom.getValue(lom.size());
    } catch (final IndexOutOfBoundsException ex) {}

    int i = 0;
    for (final MapIterator<K, V> it = lom.mapIterator(); it.hasNext(); i++) {
        it.next();
        assertSame(it.getValue(), lom.getValue(i));
}
}

public void testNullHandling_9_oe() {
    resetFull();
    try {
        map.put(null, null);
    } catch (final NullPointerException ex) {}
    assertEquals(null, map.put(new MultiKey<K>(null, null), null));
}

